// Verify maximum bounded spacing, configured append gaps, and rank assignment around rescale boundaries.
// Generated by Codex and not thoroughly checked for correctness.
func TestAssignRanks(t *testing.T) {
	gap, minimumGap := configs.ListPositionGap, configs.MinimumListPositionGap()
	lastAligned := items.MaxPosition - items.MaxPosition%gap
	for _, testCase := range []struct {
		name        string
		left, right int64
		bounded     bool
		count       int
		want        []int64
		rescale     bool
	}{
		{"append to empty list", 0, 0, false, 2, []int64{gap, 2 * gap}, false},
		{"append after last item", 2 * gap, 0, false, 2, []int64{3 * gap, 4 * gap}, false},
		{"append after an unaligned tail uses the next multiples", 2*gap + gap/2, 0, false, 2, []int64{3 * gap, 4 * gap}, false},
		{"append keeps exactly the minimum gap to the old tail", 3*gap - minimumGap, 0, false, 2, []int64{3 * gap, 4 * gap}, false},
		{"append near the next multiple inserts then rescales", 3*gap - 1, 0, false, 2, []int64{3 * gap, 4 * gap}, true},
		{"two items use maximum spacing before first anchor", 0, gap, true, 2, []int64{gap / 3, 2 * (gap / 3)}, false},
		{"three items evenly fill a power-of-two interval", 0, gap, true, 3, []int64{gap / 4, gap / 2, 3 * gap / 4}, false},
		{"bounded gaps can exceed the normal append gap", 0, 4 * gap, true, 1, []int64{2 * gap}, false},
		{"left rank need not be a power of two", 100, 100 + gap, true, 2, []int64{100 + gap/3, 100 + 2*(gap/3)}, false},
		{"minimum gap is accepted", 0, 3 * minimumGap, true, 2, []int64{minimumGap, 2 * minimumGap}, false},
		{"crowded interval inserts before rescaling", 0, 3*minimumGap - 1, true, 2, []int64{minimumGap - 1, 2 * (minimumGap - 1)}, true},
		{"gap one is insertable", 0, 3, true, 2, []int64{1, 2}, true},
		{"no integer positions remain", 0, 2, true, 2, nil, true},
		{"append can use the last aligned rank before rescaling", lastAligned - 1, 0, false, 1, []int64{lastAligned}, true},
		{"append consuming the last aligned slot rescales in advance", lastAligned - gap, 0, false, 1, []int64{lastAligned}, true},
		{"append leaves one aligned slot available", lastAligned - 2*gap, 0, false, 1, []int64{lastAligned - gap}, false},
		{"append rescales when the complete aligned batch cannot fit", lastAligned - gap, 0, false, 2, nil, true},
		{"append has no later aligned rank", lastAligned, 0, false, 1, nil, true},
		{"unaligned space near the ceiling does not shrink the configured gap", items.MaxPosition - 1, 0, false, 1, nil, true},
		{"append has no numeric space", items.MaxPosition, 0, false, 1, nil, true},
		{"empty batch", 0, 0, false, 0, nil, true},
		{"oversized batch", 0, 0, false, configs.MaxItemsPerList + 1, nil, true},
		{"negative lower bound", -1, 0, false, 1, nil, true},
		{"invalid lower bound", items.MaxPosition + 1, 0, false, 1, nil, true},
		{"reversed bounds", 200, 100, true, 1, nil, true},
		{"invalid upper bound", 0, items.MaxPosition + 1, true, 1, nil, true},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			var upper *int64
			if testCase.bounded {
				upper = &testCase.right
			}
			gap, rescale := items.InsertionGap(testCase.left, upper, testCase.count)
			var got []int64
			if gap > 0 {
				got = items.AssignRanks(testCase.left, gap, testCase.count, !testCase.bounded)
			}
			if !reflect.DeepEqual(got, testCase.want) || rescale != testCase.rescale {
				t.Fatalf("ranks=%v rescale=%v; want %v %v", got, rescale, testCase.want, testCase.rescale)
			}
		})
	}
}

// Verify the minimum maintained gap has room even for a maximum-sized incoming batch.
// Generated by Codex and not thoroughly checked for correctness.
func TestMinimumGapFitsMaximumBatch(t *testing.T) {
	right := configs.MinimumListPositionGap()
	gap, rescale := items.InsertionGap(0, &right, configs.MaxItemsPerList)
	ranks := items.AssignRanks(0, gap, configs.MaxItemsPerList, false)
	if len(ranks) != configs.MaxItemsPerList || !rescale {
		t.Fatalf("ranks=%v rescale=%v", ranks, rescale)
	}
	previous := int64(0)
	for _, rank := range ranks {
		if rank <= previous || rank >= right {
			t.Fatalf("maximum batch does not fit: previous=%d rank=%d anchor=%d", previous, rank, right)
		}
		previous = rank
	}
	if configs.ListPositionGap > items.MaxPosition/int64(configs.MaxItemsPerList) {
		t.Fatal("rescaling a full list would exceed the exact JSON integer range")
	}
}

// Verify request validation is independent of order loading and position calculation.
// Generated by Codex and not thoroughly checked for correctness.
func TestMoveValidation(t *testing.T) {
	a, b := "A", "B"
	for _, tc := range []struct {
		moves []items.Move
		valid bool
	}{
		{[]items.Move{{ProblemID: a, Before: &b}}, true}, {[]items.Move{{ProblemID: a, After: &b}}, true}, {[]items.Move{{ProblemID: a}}, true},
		{[]items.Move{{ProblemID: "judge:opaque/key"}}, true}, {[]items.Move{{ProblemID: " A "}}, true},
		{nil, false}, {[]items.Move{{ProblemID: ""}}, false}, {[]items.Move{{ProblemID: a, Before: &a}}, false}, {[]items.Move{{ProblemID: a, Before: &b, After: &b}}, false},
	} {
		err := items.ValidateMoves(tc.moves)
		if (err == nil) != tc.valid {
			t.Fatalf("%+v: %v", tc.moves, err)
		}
	}
	repository := items.NewRepository(nil, 0)
	if _, err := repository.MoveItems(t.Context(), 1, 1, nil); !errors.Is(err, items.ErrInvalidOperation) {
		t.Fatal(err)
	}
}

// Verify ordinary midpoint/append allocation and early redistribution boundaries.
// Generated by Codex and not thoroughly checked for correctness.
func TestPositionBetween(t *testing.T) {
	for _, tc := range []struct {
		left, right, want int64
		rebalance         bool
	}{
		{0, configs.ListPositionGap, configs.ListPositionGap / 2, false},
		{configs.ListPositionGap, 3 * configs.ListPositionGap, 2 * configs.ListPositionGap, false},
		{configs.ListPositionGap, items.MaxPosition, 2 * configs.ListPositionGap, false},
		{1024, 2048, 1536, true},
		{items.MaxPosition - 2, items.MaxPosition, items.MaxPosition - 1, true},
	} {
		got, rebalance := items.PositionBetween(tc.left, tc.right)
		if got != tc.want || rebalance != tc.rebalance {
			t.Fatalf("%+v: %d %v", tc, got, rebalance)
		}
	}
}

// Verify malformed bulk inputs fail before a database dependency is needed.
// Generated by Codex and not thoroughly checked for correctness.
func TestBulkValidationBeforeDatabaseAccess(t *testing.T) {
	repository := items.NewRepository(nil, 0)
	for _, input := range [][]items.ListItem{nil, {{ProblemId: " "}}, {{ProblemId: strings.Repeat("界", 101)}}, {{ProblemId: "bad\x00"}}, {{ProblemId: string([]byte{0xff})}}} {
		if _, err := repository.BulkAdd(t.Context(), 1, 1, input, nil); !errors.Is(err, items.ErrInvalidOperation) {
			t.Fatal(err)
		}
	}
	for _, ids := range [][]string{nil, {" "}, {"A", " A "}} {
		if _, err := repository.BulkRemove(t.Context(), 1, 1, ids); !errors.Is(err, items.ErrInvalidOperation) {
			t.Fatal(err)
		}
	}
}
